// Tests for PngDecoderGpu (Images/Png).
//
// Fixtures (TestData/Png, generated by scripts/images/make_png_fixtures.py) cover every colour type x bit
// depth x interlace combination, each scanline filter type forced on every row, palette alpha, gray / RGB
// colour keys, 1-pixel and 1-row images, and multi-chunk IDAT. The expected pixels (.rgba8 / .rgba16) are
// derived from the sample arrays the files were BUILT from, by the PNG spec's own scaling rules - not from
// any decoder. The generator also cross-checks the files with Pillow.
//
// What can fail: the managed overload and the ArrayView1D overload (into a caller buffer pre-filled with
// 0xAB, so a decoder that wrote elsewhere / short leaves 0xAB), RGBA8 and RGBA16 output, and the error
// paths (bad signature, bad critical CRC, truncation) which must throw ImageDecodeException with the
// specific reason.

using System.Reflection;
using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.Png;
using SpawnDev.ILGPU;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string PngFixturePrefix = "SpawnDev.Codecs.Demo.Shared.TestData.Png.";

    private static byte[] ReadEmbedded(string resourceName)
    {
        var asm = typeof(CodecsTestBase).Assembly;
        using var s = asm.GetManifestResourceStream(resourceName)
            ?? throw new InvalidOperationException($"Embedded resource not found: {resourceName}");
        using var ms = new MemoryStream();
        s.CopyTo(ms);
        return ms.ToArray();
    }

    private static string[] PngFixtureNames()
    {
        var names = typeof(CodecsTestBase).Assembly.GetManifestResourceNames()
            .Where(n => n.StartsWith(PngFixturePrefix, StringComparison.Ordinal) && n.EndsWith(".png", StringComparison.Ordinal))
            .Select(n => n.Substring(PngFixturePrefix.Length, n.Length - PngFixturePrefix.Length - 4))
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        if (names.Length == 0) throw new InvalidOperationException("No PNG fixtures are embedded.");
        return names;
    }

    private static bool HasEmbedded(string resourceName) =>
        typeof(CodecsTestBase).Assembly.GetManifestResourceNames().Contains(resourceName);

    /// <summary>Compares two pixel buffers; returns a short description of the first difference, or null.</summary>
    private static string? ComparePixels(byte[] expected, byte[] actual, int bytesPerPixel, int width)
    {
        if (expected.Length != actual.Length)
            return $"length {actual.Length} != expected {expected.Length}";
        for (int i = 0; i < expected.Length; i++)
        {
            if (expected[i] == actual[i]) continue;
            int pixel = i / bytesPerPixel;
            return $"first mismatch at byte {i} (pixel x={pixel % width} y={pixel / width} channel byte {i % bytesPerPixel}): " +
                   $"got {actual[i]}, expected {expected[i]}";
        }
        return null;
    }

    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_AllFixtures_Rgba8_MatchTruth_ManagedAndArrayView()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new PngDecoderGpu(acc);
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var name in PngFixtureNames())
            {
                byte[] png = ReadEmbedded(PngFixturePrefix + name + ".png");
                byte[] expected = ReadEmbedded(PngFixturePrefix + name + ".rgba8");
                try
                {
                    // Managed overload.
                    var managed = await dec.DecodeAsync(png);
                    int w = managed.Info.Width;
                    var diff = ComparePixels(expected, managed.Pixels, 4, w);
                    if (diff != null) failures.Add($"{name} [managed]: {diff}");

                    // ArrayView1D overload into a poisoned caller buffer, longer than needed.
                    using var dFile = acc.Allocate1D<byte>(png.Length + 11);
                    DeviceTransfer.Upload(dFile.View, png);
                    using var dOut = acc.Allocate1D<byte>(expected.Length + 7);
                    var fill = new byte[dOut.Length];
                    System.Array.Fill(fill, (byte)0xAB);
                    DeviceTransfer.Upload(dOut.View, fill);
                    var info = await dec.DecodeAsync(dFile.View, png.Length, dOut.View, PixelFormat.Rgba8);
                    var viewPixels = await DeviceTransfer.DownloadAsync(dOut.View, expected.Length);
                    diff = ComparePixels(expected, viewPixels, 4, info.Width);
                    if (diff != null) failures.Add($"{name} [ArrayView1D]: {diff}");
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(failures.Count == 0,
                $"{failures.Count} of {checkedCount + failures.Count} PNG fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_AllFixtures_Rgba16_MatchTruth()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new PngDecoderGpu(acc);
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var name in PngFixtureNames())
            {
                if (!HasEmbedded(PngFixturePrefix + name + ".rgba16")) continue;
                byte[] png = ReadEmbedded(PngFixturePrefix + name + ".png");
                byte[] expected = ReadEmbedded(PngFixturePrefix + name + ".rgba16");
                try
                {
                    var managed = await dec.DecodeAsync(png, PixelFormat.Rgba16);
                    var diff = ComparePixels(expected, managed.Pixels, 8, managed.Info.Width);
                    if (diff != null) failures.Add($"{name}: {diff}");
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(checkedCount > 0, "no 16-bit fixtures were exercised");
            True(failures.Count == 0,
                $"{failures.Count} of {checkedCount + failures.Count} RGBA16 PNG fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task PngDecoderGpu_ReadInfo_ReportsHeaderFacts()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new PngDecoderGpu(acc);
            var info = await dec.ReadInfoAsync(ReadEmbedded(PngFixturePrefix + "rgba16_il.png"));
            Equal(ImageFormat.Png, info.Format, "format");
            Equal(19, info.Width, "width");
            Equal(11, info.Height, "height");
            Equal(16, info.BitDepth, "bit depth");
            True(info.HasAlpha, "RGBA has alpha");
            True(info.IsInterlaced, "Adam7");
            Equal(1, info.FrameCount, "frames");

            var pal = await dec.ReadInfoAsync(ReadEmbedded(PngFixturePrefix + "pal8.png"));
            True(pal.HasAlpha, "palette with tRNS has alpha");
            var rgb = await dec.ReadInfoAsync(ReadEmbedded(PngFixturePrefix + "rgb8.png"));
            True(!rgb.HasAlpha, "plain RGB has no alpha");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    private async Task AssertPngRejectedAsync(byte[] file, string expectedMessagePart, string what)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new PngDecoderGpu(acc);
            ImageDecodeException? caught = null;
            try { await dec.DecodeAsync(file); }
            catch (ImageDecodeException ex) { caught = ex; }
            NotNull(caught, $"{what}: expected ImageDecodeException");
            Contains(expectedMessagePart, caught!.Message, what);
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task PngDecoderGpu_BadSignature_IsRejected()
    {
        var png = ReadEmbedded(PngFixturePrefix + "rgba8.png");
        png[1] = (byte)'X';
        await AssertPngRejectedAsync(png, "bad signature", "bad signature");
    }

    [TestMethod]
    public async Task PngDecoderGpu_CorruptIdatByte_ReportsBadCrc()
    {
        var png = ReadEmbedded(PngFixturePrefix + "rgba8.png");
        // IHDR (25 bytes with signature offset 8..32), then IDAT: flip a byte inside its payload.
        png[8 + 25 + 8 + 5] ^= 0x40;
        await AssertPngRejectedAsync(png, "bad CRC", "corrupt IDAT payload");
    }

    [TestMethod]
    public async Task PngDecoderGpu_Truncated_IsRejected()
    {
        var png = ReadEmbedded(PngFixturePrefix + "rgba8.png");
        await AssertPngRejectedAsync(png.AsSpan(0, png.Length - 20).ToArray(), "truncated", "file cut before IEND");
    }

    // ---- bounded launches: files that need many launches of every resumable stage ----

    private static void AppendHostChunk(MemoryStream file, string type, ReadOnlySpan<byte> data)
    {
        var body = new byte[4 + data.Length];
        for (int i = 0; i < 4; i++) body[i] = (byte)type[i];
        data.CopyTo(body.AsSpan(4));
        uint len = (uint)data.Length;
        file.Write(new[] { (byte)(len >> 24), (byte)(len >> 16), (byte)(len >> 8), (byte)len });
        file.Write(body);
        uint crc = HostCrc(body);
        file.Write(new[] { (byte)(crc >> 24), (byte)(crc >> 16), (byte)(crc >> 8), (byte)crc });
    }

    /// <summary>
    /// A non-interlaced PNG built on the host: random filtered scanlines whose filter types cycle 0..4 row by row,
    /// compressed by .NET's zlib, the IDAT stream cut into chunks of <paramref name="idatChunk"/> bytes (0 = one chunk).
    /// </summary>
    private static byte[] BuildHostPng(int w, int h, int colorType, int depth, int seed, int idatChunk, System.IO.Compression.CompressionLevel level)
    {
        int channels = colorType switch { 0 => 1, 2 => 3, 4 => 2, _ => 4 };
        int rowBytes = w * channels * depth / 8;
        var raw = new byte[h * (rowBytes + 1)];
        new Random(seed).NextBytes(raw);
        for (int y = 0; y < h; y++) raw[y * (rowBytes + 1)] = (byte)(y % 5);
        byte[] zlib = ZlibCompress(raw, level);

        var file = new MemoryStream();
        file.Write(new byte[] { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A });
        var ihdr = new byte[13];
        ihdr[0] = (byte)(w >> 24); ihdr[1] = (byte)(w >> 16); ihdr[2] = (byte)(w >> 8); ihdr[3] = (byte)w;
        ihdr[4] = (byte)(h >> 24); ihdr[5] = (byte)(h >> 16); ihdr[6] = (byte)(h >> 8); ihdr[7] = (byte)h;
        ihdr[8] = (byte)depth;
        ihdr[9] = (byte)colorType;
        AppendHostChunk(file, "IHDR", ihdr);
        int step = idatChunk > 0 ? idatChunk : zlib.Length;
        for (int p = 0; p < zlib.Length; p += step)
            AppendHostChunk(file, "IDAT", zlib.AsSpan(p, Math.Min(step, zlib.Length - p)));
        AppendHostChunk(file, "IEND", ReadOnlySpan<byte>.Empty);
        return file.ToArray();
    }

    private async Task AssertPngMatchesHostReaderAsync(byte[] png, bool sixteen, string what)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            var host = ReadPngOnHost(png);
            using var dec = new PngDecoderGpu(acc);
            if (!sixteen)
            {
                var got = await dec.DecodeAsync(png);
                var diff = ComparePixels(host.Rgba8, got.Pixels, 4, host.Width);
                True(diff == null, $"{what}: {diff}");
            }
            else
            {
                var got = await dec.DecodeAsync(png, PixelFormat.Rgba16);
                var expected = new byte[host.Rgba16.Length * 2];
                for (int i = 0; i < host.Rgba16.Length; i++) { expected[2 * i] = (byte)host.Rgba16[i]; expected[2 * i + 1] = (byte)(host.Rgba16[i] >> 8); }
                var diff = ComparePixels(expected, got.Pixels, 8, host.Width);
                True(diff == null, $"{what}: {diff}");
            }
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    /// <summary>
    /// 1600x1450 RGBA8 noise in ONE 9.3 MB IDAT chunk: inflate runs thousands of bounded launches, unfilter about 70
    /// (launch ranges end mid-row), the chunk's CRC is over 1024 pieces so its combine takes two launches.
    /// </summary>
    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_LargeImage_OneBigIdat_MatchesHostReader() =>
        await AssertPngMatchesHostReaderAsync(
            BuildHostPng(1600, 1450, 6, 8, 0x7A01, 0, System.IO.Compression.CompressionLevel.Fastest), false, "1600x1450 RGBA8, one IDAT");

    /// <summary>The CRC of a 1000+-piece chunk is checked after a multi-launch combine: a flipped byte in its last piece must be caught.</summary>
    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_LargeImage_CorruptBigIdat_ReportsBadCrc()
    {
        var png = BuildHostPng(1600, 1450, 6, 8, 0x7A02, 0, System.IO.Compression.CompressionLevel.Fastest);
        // IEND is the last 12 bytes; the IDAT CRC the 4 before them; flip a payload byte just before that.
        png[png.Length - 12 - 4 - 100] ^= 0x10;
        await AssertPngRejectedAsync(png, "bad CRC", "corrupt byte in the last CRC piece of a 9 MB IDAT");
    }

    /// <summary>RGB16 (6 filter-byte lanes), 700x500: unfilter launch ranges of 6 lanes end mid-row; RGBA16 output.</summary>
    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_LargeRgb16_SixLanes_MatchesHostReader() =>
        await AssertPngMatchesHostReaderAsync(
            BuildHostPng(700, 500, 2, 16, 0x7A03, 0, System.IO.Compression.CompressionLevel.Optimal), true, "700x500 RGB16");

    /// <summary>Gray8 (one lane), 2000x1000: the single-lane unfilter over many launches.</summary>
    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_LargeGray8_OneLane_MatchesHostReader() =>
        await AssertPngMatchesHostReaderAsync(
            BuildHostPng(2000, 1000, 0, 8, 0x7A04, 65536, System.IO.Compression.CompressionLevel.Optimal), false, "2000x1000 gray8");

    /// <summary>The IDAT stream cut into 8-byte chunks: over 9000 chunks, so the chunk scan takes three launches.</summary>
    [TestMethod(Timeout = 600000)]
    public async Task PngDecoderGpu_ManySmallIdatChunks_MatchesHostReader()
    {
        var png = BuildHostPng(160, 120, 6, 8, 0x7A05, 8, System.IO.Compression.CompressionLevel.Optimal);
        True(ReadPngOnHost(png).IdatCount > 2 * PngKernels.ScanChunks, "the file must need several scan launches");
        await AssertPngMatchesHostReaderAsync(png, false, "160x120 RGBA8 in 8-byte IDAT chunks");
    }
}
